package com.datacenter.etl.controller;

import org.springframework.batch.core.JobExecution;
import org.springframework.batch.core.StepExecution;
import org.springframework.batch.core.explore.JobExplorer;
import org.springframework.http.ResponseEntity;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.*;
import java.util.Collection;

@RestController
@RequestMapping("/batch/etl")
public class BatchStepLogController {

    private final JobExplorer jobExplorer;

    public BatchStepLogController(JobExplorer jobExplorer) {
        this.jobExplorer = jobExplorer;
    }

    @GetMapping("/executions/{executionId}/steps")
    public ResponseEntity<Collection<StepExecution>> getStepExecutions(
            @PathVariable Long executionId,
            Authentication authentication) {
        JobExecution execution = jobExplorer.getJobExecution(executionId);
        if (execution == null) {
            return ResponseEntity.notFound().build();
        }
        String businessUnit = execution.getJobParameters().getString("businessUnit");
        if (businessUnit == null || !businessUnit.equalsIgnoreCase(authentication.getName())) {
            throw new AccessDeniedException("Not authorized to view step executions for this business unit");
        }
        return ResponseEntity.ok(execution.getStepExecutions());
    }
}
